UnitOfMeasureSymbol displayUnitId()
{
    ModuleInventPurchSales priceType;

    switch (this.PriceType)
    {
        case GUPBasePriceType::BasePricePurchase:
            priceType = ModuleInventPurchSales::Purch;
            break;
        case GUPBasePriceType::BasePriceSales:
            priceType = ModuleInventPurchSales::Sales;
            break;
        case GUPBasePriceType::BasePriceInventoryCost:
            priceType = ModuleInventPurchSales::Invent;
            break;
    }

    return InventTableModule::find(this.ItemId, priceType).UnitId;
}

public void initFromInventItemPriceMap(GUPItemBasePriceMap      _itemBasePriceMap,
                                       GUPBasePriceVersionId    _versionId,
                                       Price                    _price)
{
    this.InventDimId            = _itemBasePriceMap.InventDimId;
    this.ItemId                 = _itemBasePriceMap.ItemId;
    this.FromDate               = _itemBasePriceMap.FromDate;
    this.ToDate                 = _itemBasePriceMap.ToDate;
    this.Markup                 = _itemBasePriceMap.Markup;
    this.MarkupQty              = _itemBasePriceMap.MarkupQty;
    this.Price                  = _price;
    this.PriceAllocateMarkup    = _itemBasePriceMap.PriceAllocateMarkup;
    this.PriceQty               = _itemBasePriceMap.PriceQty;
    this.PriceType              = _itemBasePriceMap.PriceType;
    this.UnitID                 = _itemBasePriceMap.UnitID;
    this.VersionId              = _versionId;
    this.PriceCalcId            = _itemBasePriceMap.PriceCalcId;
}
